const items = $input.all();

return items.map(item => {
  const data = item.json;

  const prixSysteme = data.PRI_0;
  const prixDevis = data.tarif_devis;

  let ecart_montant = null;
  let ecart_pourcentage = null;

  if (prixSysteme !== null && prixSysteme !== undefined && prixSysteme !== 0) {
    ecart_montant = prixDevis - prixSysteme;
    ecart_pourcentage = (ecart_montant / prixSysteme) * 100;
  }

  return {
    json: {
      ...data,
      ecart_montant: ecart_montant !== null ? Math.round(ecart_montant * 100) / 100 : null,
      ecart_pourcentage: ecart_pourcentage !== null ? Math.round(ecart_pourcentage * 100) / 100 : null
    }
  };
});

const crypto = require('crypto');

// Données fournisseur (input de ce node)
const fournisseur = $input.first().json;

// Données article/prix (node 'If1')
const articleData = $("If1").first().json;

// ─────────────────────────────────────────────
// Génération de l'identifiant RFPN
// ─────────────────────────────────────────────
const now = new Date();
const annee = now.getFullYear();
const mois = String(now.getMonth() + 1).padStart(2, '0');
const jour = String(now.getDate()).padStart(2, '0');
const heure = String(now.getHours()).padStart(2, '0');
const minute = String(now.getMinutes()).padStart(2, '0');
const seconde = String(now.getSeconds()).padStart(2, '0');

const uuid = crypto.randomUUID();
const shortUuid = uuid.substring(0, 4).toUpperCase();

const numero_rfpn = `RFPN-${annee}-${mois}${jour}${heure}${minute}${seconde}-${shortUuid}`;

// ─────────────────────────────────────────────
// Données extraites
// ─────────────────────────────────────────────
const rfq_number = articleData.number_rfq;
const code_article = articleData.code_article;
const designation_article = articleData.designation_article;
const prix_unitaire = articleData.tarif_devis;
const prix_unitaire_sys = articleData.PRI_0;
const quantite_disponible = articleData.quantite_disponible || 1;
const ecart_pourcentage = articleData.ecart_pourcentage;
const ecart_montant = articleData.ecart_montant;

const nom_fournisseur = fournisseur.BPRNAM_0;
const email_fournisseur = fournisseur.WEB_0;
const code_fournisseur = fournisseur.BPANUM_0;

// ─────────────────────────────────────────────
// Corps HTML de l'email
// ─────────────────────────────────────────────
const email_html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
</head>
<body style="font-family: Arial, sans-serif; color: #1f2937; max-width: 600px; margin: 0 auto;">

  <div style="background: #2d5a87; padding: 20px; border-radius: 8px 8px 0 0;">
    <h2 style="color: white; margin: 0;">Demande de révision tarifaire</h2>
    <p style="color: #dbeafe; margin: 5px 0 0;">Référence: ${numero_rfpn}</p>
  </div>

  <div style="padding: 24px; border: 1px solid #e5e7eb; border-top: none;">
    <p>Bonjour ${nom_fournisseur},</p>

    <p>
      Nous avons bien reçu votre offre de prix suite à notre demande de cotation
      <strong>${rfq_number}</strong>. Après comparaison avec nos tarifs de référence,
      nous constatons un écart significatif sur l'article suivant :
    </p>

    <table style="width: 100%; border-collapse: collapse; margin: 20px 0;">
      <tr style="background: #f9fafb;">
        <td style="padding: 10px; border: 1px solid #e5e7eb; font-weight: 600;">Code Article</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb;">${code_article}</td>
      </tr>
      <tr>
        <td style="padding: 10px; border: 1px solid #e5e7eb; font-weight: 600;">Désignation</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb;">${designation_article}</td>
      </tr>
      <tr style="background: #f9fafb;">
        <td style="padding: 10px; border: 1px solid #e5e7eb; font-weight: 600;">Quantité souhaitée</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb;">${quantite_disponible}</td>
      </tr>
      <tr>
        <td style="padding: 10px; border: 1px solid #e5e7eb; font-weight: 600;">Votre prix proposé</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb; color: #dc2626; font-weight: 600;">
          ${prix_unitaire} MAD
        </td>
      </tr>
      <tr style="background: #f9fafb;">
        <td style="padding: 10px; border: 1px solid #e5e7eb; font-weight: 600;">Notre prix de référence</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb; color: #059669; font-weight: 600;">
          ${prix_unitaire_sys} MAD
        </td>
      </tr>
      <tr>
        <td style="padding: 10px; border: 1px solid #e5e7eb; font-weight: 600;">Écart constaté</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb;">
          +${ecart_montant} MAD (+${ecart_pourcentage}%)
        </td>
      </tr>
    </table>

    <p>
      Afin de poursuivre notre collaboration, nous vous invitons à revoir votre proposition
      tarifaire et à nous transmettre un prix plus proche de notre référence interne, si possible.
    </p>

    <p>
      Merci de bien vouloir nous faire part de votre nouvelle proposition en réponse à cet email,
      en conservant la référence <strong>${numero_rfpn}</strong> dans l'objet.
    </p>

    <p style="margin-top: 30px;">
      Cordialement,<br>
      Service Achats
    </p>
  </div>

  <div style="background: #f9fafb; padding: 12px 24px; border-radius: 0 0 8px 8px; font-size: 12px; color: #9ca3af;">
    Référence RFQ initiale: ${rfq_number} | Référence RFPN: ${numero_rfpn}
  </div>

</body>
</html>
`;

// ─────────────────────────────────────────────
// Retour
// ─────────────────────────────────────────────
return {
  numero_rfpn: numero_rfpn,
  rfq_number: rfq_number,
  code_article: code_article,
  designation_article: designation_article,
  prix_unitaire: prix_unitaire,
  prix_unitaire_sys: prix_unitaire_sys,
  quantite_disponible: quantite_disponible,
  ecart_montant: ecart_montant,
  ecart_pourcentage: ecart_pourcentage,
  code_fournisseur: code_fournisseur,
  nom_fournisseur: nom_fournisseur,
  email_fournisseur: email_fournisseur,
  email_html: email_html,
  email_subject: `Demande de révision tarifaire ${numero_rfpn}`,
  date_envoi: new Date().toISOString()
};
